/*
 *	sk_utron.c
 *	ソフトウェアキーボード: the μTRON keyboard (design 11.31)
 *
 *	The μTRON keyboard's two halves and 76 keys as its layout chart
 *	draws them, every mark on the keys -- the letters, the kana of the
 *	three faces in black, red and blue, the small boxes of F1, PgUp and
 *	the others -- as outlines of filled shapes, on a plane of 842 x 595
 *	units in tenths of a unit. A line drawn in the chart is the outline
 *	of a band as wide as the line. Each key has its outline (the keys
 *	are upright; tab and 改行 are L-shaped), what it types (the usage
 *	whose TRON かな it types, for kana; the letters of its faces, typed
 *	as whatever usage types them in the latin layout set), and the
 *	marks drawn on it. The keys are named by half (L, R), row from the
 *	top and place in the row from the left.
 */

